fn is_greater(n: i32, a: Vec<i32>) -> bool {
    // Iterate through each element in the array.
    // If we find any element that is >= n, we know
    // `n` is not strictly greater than all elements,
    // so we can return false immediately.
    for &elem in &a {
        if elem >= n {
            return false;
        }
    }
    // If we never found such an element, then `n`
    // is strictly greater than every element (or
    // the array was empty), so we return true.
    true
}

